<?php
declare(strict_types=1);
$h=static fn(string $v):string=>htmlspecialchars($v,ENT_QUOTES,'UTF-8');
$date=static fn(string $v):string=>$v!==''?(new DateTimeImmutable($v))->format('d/m/Y H:i'):'—';
?>
<section class="gnre-panel real-batch-pilot">
  <header><h2>Lote real GNRE — piloto</h2><p>Este piloto transmite as guias selecionadas em uma única solicitação ao Portal.</p><p>Disponível exclusivamente para lotes de <strong>Homologação</strong>. Não baixa nem associa PDF.</p></header>
  <?php if($realBatchPilotFlash): ?><p class="<?=$realBatchPilotFlash['error']?'error':'success'?>"><?=$h((string)$realBatchPilotFlash['message'])?></p><?php endif; ?>
  <?php if(!$realBatchPilotAvailable): ?><p class="error">O schema mínimo da Task 74 ainda não está disponível nesta base. O piloto permanece desativado; nenhuma transmissão será feita.</p><?php endif; ?>
  <section class="real-batch-selection"><h3>Selecionar guias elegíveis</h3><p>Somente rascunhos em Homologação, sem transmissão anterior, são exibidos. As guias escolhidas devem ter a mesma UF e o mesmo snapshot; incompatibilidades são recusadas sem criar lote.</p>
  <?php if(!$realBatchPilotCandidates): ?><p>Nenhuma guia elegível em Homologação está disponível.</p><?php else: ?><form method="post" action="<?=$h(gnre_url('?view=real_batch_pilot'))?>"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="prepare_real_batch_pilot"><div class="table-wrap"><table class="guide-table"><thead><tr><th></th><th>Guia</th><th>UF</th><th>Receita</th><th>Valor</th></tr></thead><tbody><?php foreach($realBatchPilotCandidates as $guide): ?><tr><td><input type="checkbox" name="guide_ids[]" value="<?=(int)$guide['GNRE001_Id']?>" aria-label="Selecionar guia #<?=(int)$guide['GNRE001_Id']?>"></td><td>#<?=(int)$guide['GNRE001_Id']?></td><td><?=$h((string)$guide['GNRE001_UF_Favorecida'])?></td><td><?=$h((string)$guide['_projected_revenue'])?></td><td>R$ <?=number_format((float)$guide['GNRE001_Valor'],2,',','.')?></td></tr><?php endforeach; ?></tbody></table></div><button type="submit" <?=$realBatchPilotAvailable?'':'disabled'?>>Preparar lote piloto</button></form><?php endif; ?></section>
  <?php $eligible=array_filter($realBatchPilotLots,static fn(array $lot):bool=>(string)$lot['environment']==='2'); ?>
  <?php if(!$eligible): ?><p>Não há lote preparado em Homologação. A preparação e a Fila sequencial são fluxos separados.</p><?php else: ?><div class="table-wrap"><table class="guide-table"><thead><tr><th>Lote</th><th>UF</th><th>Estado</th><th>Guias</th><th>Recibo</th><th>Ação</th></tr></thead><tbody>
  <?php foreach($eligible as $lot): $status=(string)$lot['status']; ?><tr><td>#<?=(int)$lot['id']?></td><td><?=$h((string)$lot['uf'])?></td><td><?=$h($status)?></td><td><ul class="real-batch-guides"><?php foreach((array)$lot['guides'] as $guide): ?><li>#<?=(int)$guide['id']?> — <?=$h((string)$guide['status'])?></li><?php endforeach; ?></ul></td><td><?=$h((string)($lot['receipt']?:'—'))?></td><td><?php if(!$realBatchPilotAvailable): ?>Schema pendente.<?php elseif($status==='PREPARADO'): ?><form method="post" action="<?=$h(gnre_url('?view=real_batch_pilot'))?>" onsubmit="return confirm('Confirmo o envio único destas guias ao Portal de Homologação.');"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="send_real_batch_pilot"><input type="hidden" name="cohort_id" value="<?=(int)$lot['id']?>"><button type="submit">Transmitir lote piloto</button></form><?php elseif(in_array($status,['RECEBIDO','PENDENTE'],true)): ?><form method="post" action="<?=$h(gnre_url('?view=real_batch_pilot'))?>"><input type="hidden" name="csrf" value="<?=$h($csrf)?>"><input type="hidden" name="action" value="consult_real_batch_pilot"><input type="hidden" name="cohort_id" value="<?=(int)$lot['id']?>"><button type="submit">Consultar resultado do lote</button></form><?php else: ?>Bloqueado para retransmissão automática.<?php endif; ?></td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?>
</section>
